function I(name,size=19){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.spark}</svg>`;}
const navs=[
 ['landscape','sun','Emotion Landscape','অনুভূতির আকাশ'],['garden','leaf','Mind Garden','মনের বাগান'],['journey','book','Life Journey','জীবনের সফর'],['journal','book','Private journal','ব্যক্তিগত জার্নাল'],['plan','calendar','My wellbeing plan','আমার পরিকল্পনা'],['insights','chart','My insights','আমার তথ্য'],['mindmap','target','Mind Map','মনের মানচিত্র'],['relaxation','wind','Relaxation room','শান্তির ঘর'],
 ['dashboard','grid','Dashboard','ড্যাশবোর্ড'],['moods','heart','Mood assessment','অনুভূতি যাচাই'],['diary','calendar','Mood diary','মুড ডায়েরি'],['challenges','check','Gentle challenges','সহজ অভ্যাস'],['scenarios','book','Life scenarios','জীবনের পরিস্থিতি'],
 ['bromind','wind','Bro-minD Plus','ব্রো-মিন্ড প্লাস'],['companion','message','Companion','সহায়ক সঙ্গী'],['support','users','Support directory','সহায়তার ঠিকানা'],['research','chart','Research insights','গবেষণার তথ্য'],['access','shield','Accessibility & privacy','অ্যাক্সেসিবিলিটি'],['connect','users','Professional connection','বিশেষজ্ঞ সহায়তা']
];
function pageNow(){return (location.hash.replace(/^#\/?/,'').split('/')[0]||'home').toLowerCase();}
function go(path){location.hash=href(path);if(pageNow()===path.split('/')[0])render();}
function header(){const page=pageNow();return `<aside class="sidebar" aria-label="Primary navigation">
  <a href="#/home" class="brand"> <span class="brand-mark">${I('leaf',25)}</span><span>mind<span class="brand-highlight">sage</span><small>STUDENT WELLBEING</small></span></a>
  <div class="side-caption">${T('YOUR SPACE','আপনার স্থান')}</div><nav class="side-menu">${navs.map(([p,i,en,bn])=>`<a href="#/${p}" class="side-item ${page===p||(p==='moods'&&['assessment','report'].includes(page))?'active':''}">${I(i)} <span>${T(en,bn)}</span>${p==='bromind'?'<b class="new-badge">PLUS</b>':''}</a>`).join('')}</nav>
  <div class="sidebar-bottom"><div class="side-quote"><span>✦</span><p>${T('You deserve a space to pause.','একটু থামার জন্য আপনারও স্থান আছে।')}</p></div><a href="#/privacy" class="side-privacy">${I('shield',16)} ${T('Privacy & data','গোপনীয়তা')}</a></div>
 </aside>`;}
function shell(body,compact=false){const hasProfile=state.level!=null;return `<div class="app-shell">${header()}<div class="main-area"><header class="topbar"><button class="menu-icon" id="menu-toggle" aria-label="${T('Open navigation','নেভিগেশন খুলুন')}" aria-expanded="false">${I('grid')}</button><div class="breadcrumb">${I('leaf',15)} <span>Mind-sage</span><span class="sep">/</span><strong>${esc((navs.find(x=>x[0]===pageNow())||[])[state.lang==='bn'?3:2]||T('Your wellbeing space','আপনার ভালো থাকার স্থান'))}</strong></div><div class="top-actions"><span class="privacy-tag">${I('lock',13)} ${T('Private by design','গোপনীয়তাকে গুরুত্ব')}</span><button class="lang-btn" data-action="lang" aria-label="${T('Switch to Bengali','Switch to English')}">${I('book',15)} ${state.lang==='bn'?'English':'বাংলা'}</button><a class="avatar" href="#/${hasProfile?'dashboard':'home'}" aria-label="${T('Go to dashboard','ড্যাশবোর্ড')}">${I('users',18)}</a></div></header><main class="content ${compact?'content-wide':''}" id="main-content">${body}</main><footer class="footer"><span>© ${new Date().getFullYear()} Mind-sage · ${T('Designed for moments that matter','মানসিক সুস্থতার সহযাত্রী')}</span><span><a href="#/privacy">${T('Privacy','গোপনীয়তা')}</a> · <a href="#/support">${T('Find support','সহায়তা')}</a></span></footer></div><div class="nav-shade" id="nav-shade"></div></div>`;}
function meta(k){return `<span class="eyebrow">${esc(k)}</span>`;}
function pill(t,cl=''){return `<span class="pill ${cl}">${t}</span>`;}
function cta(path,text,secondary=false){return `<a href="#/${path}" class="btn ${secondary?'btn-soft':'btn-solid'}">${text} ${I('arrow',16)}</a>`;}
function head(k,h,p){return `<div class="page-title">${meta(k)}<h1>${h}</h1><p>${p}</p></div>`;}
function categoryCards(){return `<div class="level-grid">${LEVELS.map((l,i)=>`<button class="level-card" data-action="level" data-id="${l.id}"><span class="level-index">0${i+1}</span><span class="level-icon">${I(['book','sun','grid','chart','spark'][i],24)}</span><h3>${esc(nameOf(l.id))}</h3><p>${esc(T(l.subtitle, ['সহজভাবে নিজের অনুভূতি বলুন।','পড়াশোনা ও জীবনের পরিবর্তন নিয়ে ভাবুন।','কলেজজীবনের ব্যস্ততায় একটু থামুন।','পড়াশোনা ও জীবনের ভারসাম্য খুঁজুন।','গবেষণার পথে নিজের যত্ন নিন।'][i]))}</p><span class="level-next">${I('arrow',17)}</span></button>`).join('')}</div>`;}
function landing(){return shell(`<section class="hero-intro"><div class="hero-content">${pill(T('A thoughtful wellbeing experience','আপনার মানসিক সুস্থতার সহযাত্রী'),'light')}<h1>${T('A calmer mind.<br><em>A brighter way forward.</em>','শান্ত মন।<br><em>নতুন পথের আলোর দিশা।</em>')}</h1><p>${T('A welcoming space to understand your emotions, build steady habits, and find support that fits your student journey.','নিজের অনুভূতি বোঝা, ভালো অভ্যাস গড়া এবং প্রয়োজনীয় সহায়তা খুঁজে পাওয়ার একটি আন্তরিক স্থান।')}</p><div class="hero-actions">${cta('bromind',T('Explore Bro-minD Plus','ব্রো-মিন্ড প্লাস দেখুন'))}${cta('support',T('Find support','সহায়তা খুঁজুন'),true)}</div><div class="hero-proof">${I('shield',16)} ${T('No account needed · Answers stay in your browser','অ্যাকাউন্টের প্রয়োজন নেই · উত্তর ব্রাউজারেই থাকে')}</div></div><div class="hero-art" aria-hidden="true"><div class="art-ring ring-1"></div><div class="art-ring ring-2"></div><div class="art-orbit"><span>✦</span><span>✧</span></div><div class="art-person"><span class="art-sun">✺</span><div class="art-body"></div><div class="art-head"></div><div class="art-hair"></div><div class="art-leaf leaf-a"></div><div class="art-leaf leaf-b"></div></div><div class="float-card float-one">${I('heart',17)} ${T('Feel understood','নিজেকে বুঝুন')}</div><div class="float-card float-two">${I('sun',17)} ${T('Find balance','ভারসাম্য খুঁজুন')}</div></div></section>
<section class="under-hero"><span>${I('shield',15)} ${T('Private check-ins','ব্যক্তিগত মূল্যায়ন')}</span><span>${I('wind',15)} ${T('Grounding and meditation','ধ্যান ও শ্বাসের ব্যায়াম')}</span><span>${I('book',15)} ${T('English and Bengali','বাংলা ও ইংরেজি')}</span><span>${I('heart',15)} ${T('Support when needed','প্রয়োজনে সহায়তা')}</span></section>
<section class="section-space"><div class="section-heading">${meta(T('BEGIN YOUR JOURNEY','শুরু করুন'))}<h2>${T('Which learning stage best describes you?','আপনি কোন শিক্ষার স্তরে আছেন?')}</h2><p>${T('Choose a student category to continue to your personal wellbeing dashboard.','নিজের শিক্ষার স্তর বেছে নিয়ে পরবর্তী ধাপে যান।')}</p></div>${categoryCards()}</section>
<section class="home-footer-panels"><article><div class="icon-bubble">${I('wind',27)}</div><div><h3>${T('A little calm can go a long way.','একটু শান্তি এনে দিতে পারে স্বস্তি।')}</h3><p>${T('Try breathing, grounding and mindful reflection at your own pace.','নিজের গতিতে শ্বাস, মনোযোগ ও ধ্যান অনুশীলন করুন।')}</p>${cta('bromind',T('Visit Bro-minD Plus','ব্রো-মিন্ড প্লাস'))}</div></article><article class="dark"><div class="icon-bubble">${I('book',27)}</div><div><h3>${T('Wisdom to carry with you.','মননে স্বামীজীর বাণী।')}</h3><p>${T('Explore sourced Bengali sayings from Swami Vivekananda.','স্বামী বিবেকানন্দের উৎসসহ নির্বাচিত বাংলা বাণী পড়ুন।')}</p>${cta('vani',T('Explore Vani','বাণী পড়ুন'),true)}</div></article></section>`,true);}
function generateCaptcha(){const old=state.captcha;const rand=n=>{const a=new Uint32Array(1);if(window.crypto?.getRandomValues){crypto.getRandomValues(a);return a[0]%n;}return Math.floor(Math.random()*n);};const a=2+rand(12),b=2+rand(9),op=rand(2)===0?'+':'−';state.captcha={a,b,op,value:op==='+'?a+b:a-b};if(old&&old.a===a&&old.b===b&&old.op===op){state.captcha.b=(b%10)+1;state.captcha.value=op==='+'?a+state.captcha.b:a-state.captcha.b;}}
function profile(){if(!state.level)return go('home'); if(!state.captcha)generateCaptcha(); return shell(`<div class="back-row"><a href="#/home">${I('back',15)} ${T('Change student category','শিক্ষার স্তর বদলান')}</a></div>${head(T('STEP 01 · GETTING STARTED','ধাপ ০১ · শুরু করুন'),T('A few details to get started.','শুরু করতে কিছু তথ্য দিন।'),T('These details help us display age-appropriate guidance. Your date of birth is not saved on a server.','বয়স অনুযায়ী তথ্য দেখাতে এগুলো দরকার। জন্মতারিখ কোনো সার্ভারে রাখা হয় না।'))}<div class="form-layout"><form id="profile-form" class="surface-card form-card"><div class="form-top">${I('users',23)} <div><strong>${esc(nameOf(state.level))}</strong><small>${T('Selected learning stage','নির্বাচিত শিক্ষার স্তর')}</small></div></div><div class="two-col"><label class="field"><span>${T('Date of birth','জন্মতারিখ')} <b>*</b></span><input id="dob" name="dob" type="date" required max="${dateStamp()}" value="${esc(state.dob)}"/><small>${T('Choose from the calendar','ক্যালেন্ডার থেকে বেছে নিন')}</small></label><label class="field"><span>${T('Gender','লিঙ্গ')} <b>*</b></span><select id="gender" name="gender" required><option value="">${T('Select an option','একটি বিকল্প বেছে নিন')}</option>${[['Male','Male','পুরুষ'],['Female','Female','মহিলা'],['Other','Other','অন্যান্য'],['Prefer not to disclose','Prefer not to disclose','জানাতে চাই না']].map(([v,en,bn])=>`<option value="${v}" ${state.gender===v?'selected':''}>${T(en,bn)}</option>`).join('')}</select></label></div><div class="captcha"><div><strong>${T('Quick verification','সহজ যাচাই')}</strong><p>${T('Solve the small calculation to continue.','এগোতে ছোট হিসাবটির উত্তর দিন।')}</p></div><div class="captcha-line"><span class="captcha-math" aria-label="Math verification">${state.captcha.a} ${state.captcha.op} ${state.captcha.b} = ?</span><input name="captcha" inputmode="numeric" pattern="-?[0-9]+" required autocomplete="off" aria-label="${T('Captcha answer','যাচাইয়ের উত্তর')}" placeholder="${T('Answer','উত্তর')}"/><button type="button" data-action="captcha" class="icon-button" aria-label="${T('New captcha','নতুন অঙ্ক')}">${I('refresh')}</button></div></div><div class="form-error" id="profile-error" role="alert"></div><button class="btn btn-solid btn-full" type="submit">${T('Continue to your dashboard','ড্যাশবোর্ডে যান')} ${I('arrow',17)}</button></form><aside class="form-aside"><div class="aside-symbol">${I('shield',37)}</div><h3>${T('Your wellbeing, on your terms.','আপনার অনুভূতি, আপনার সিদ্ধান্ত।')}</h3><p>${T('There is no login. Your questionnaire responses stay in this browser session. Adults can choose to save diary entries locally; younger students use session-only entries.','লগইন লাগে না। প্রশ্নের উত্তর কেবল এই ব্রাউজার সেশনে থাকে। প্রাপ্তবয়স্করা চাইলে ডায়েরি ডিভাইসে রাখতে পারেন; অপ্রাপ্তবয়স্কদের তথ্য সেশনেই থাকে।')}</p><ul><li>${T('No background upload','গোপনে তথ্য আপলোড নয়')}</li><li>${T('You decide whether to save','সেভ করবেন কি না আপনি ঠিক করবেন')}</li><li>${T('Help resources remain available to everyone','সবার জন্য সহায়তার তথ্য থাকবে')}</li></ul><a href="#/privacy">${T('How privacy works','গোপনীয়তার বিস্তারিত')} ${I('arrow',15)}</a></aside></div>`);}
function selectedLevelWelcome(){return ({primary:['A small step is a good beginning.','একটু চেষ্টা দিয়েই শুরু হয়।'],high:['Your feelings deserve attention.','আপনার অনুভূতি গুরুত্বপূর্ণ।'],ug:['Create space for yourself between classes.','ক্লাসের ফাঁকে নিজের সময় খুঁজুন।'],pg:['A balanced journey begins with a pause.','কিছুক্ষণ থামলেই ভারসাম্য খুঁজে পাওয়া যায়।'],phd:['Care for the person behind the research.','গবেষণার পাশাপাশি নিজের যত্নও জরুরি।']})[state.level]||['Welcome to your space.','আপনার স্থানটি আপনাকে স্বাগত জানায়।'];}
function dashboard(){if(!state.level)return landing();const recent=state.entries.filter(e=>e.kind==='mood').slice(-1)[0];return shell(`<div class="dashboard-greeting"><div>${meta(T('YOUR PERSONAL SPACE','আপনার ব্যক্তিগত স্থান'))}<h1>${T('Welcome to your space.','আপনার নিজের জায়গায় স্বাগতম।')}</h1><p>${T(...selectedLevelWelcome())}</p></div>${pill(esc(nameOf(state.level)),'soft')}</div><section class="dash-hero"><div>${pill(T('DAILY WELLBEING','প্রতিদিনের যত্ন'),'light')}<h2>${T('How are you feeling<br>right now?','এই মুহূর্তে<br>আপনার কেমন লাগছে?')}</h2><p>${T('A thoughtful check-in is a small way to give yourself attention.','নিজের অনুভূতি বোঝার জন্য একটু সময় রাখুন।')}</p>${cta('moods',T('Begin a check-in','মুড যাচাই শুরু করুন'))}</div><div class="dash-art" aria-hidden="true"><div class="dash-disc"><span>✿</span></div><span class="star-one">✦</span><span class="star-two">✧</span></div></section><div class="stat-grid"><article class="stat-card"><span class="stat-icon icon-mint">${I('calendar',22)}</span><div><span>${T('Private diary entries','ব্যক্তিগত ডায়েরি')}</span><strong>${state.entries.filter(e=>e.kind==='mood').length}</strong><small>${T('Saved in this browser or session','ব্রাউজার বা এই সেশনে')}</small></div></article><article class="stat-card"><span class="stat-icon icon-peach">${I('heart',22)}</span><div><span>${T('Last mood check','শেষ মুড যাচাই')}</span><strong>${recent?esc(recent.mood):T('Not yet','এখনও নয়')}</strong><small>${recent?fmtDate(recent.time):T('Begin whenever you are ready','ইচ্ছা হলেই শুরু করুন')}</small></div></article><article class="stat-card"><span class="stat-icon icon-lavender">${I('shield',22)}</span><div><span>${T('Personal privacy','ব্যক্তিগত গোপনীয়তা')}</span><strong>${T('On device','ডিভাইসে')}</strong><small>${T('No backend or account required','সার্ভার বা অ্যাকাউন্ট লাগবে না')}</small></div></article></div><section class="section-space compact"><div class="between-title"><div><span class="eyebrow">${T('CHECK IN','মুড যাচাই')}</span><h2>${T('What best describes today?','আজ আপনার অনুভূতি কেমন?')}</h2></div><a class="inline-link" href="#/moods">${T('View all','সব দেখুন')} ${I('arrow',16)}</a></div><div class="mood-tiles">${moodCards(true)}</div></section><section class="section-space compact"><div class="between-title"><div><span class="eyebrow">${T('YOUR WELLBEING TOOLKIT','আপনার সুস্থতার সহায়ক')}</span><h2>${T('Support for every kind of day.','প্রতিটি দিনের জন্য কিছু সহায়তা।')}</h2></div></div><div class="tool-preview"><a href="#/breathing" class="tool-preview-card"><span class="tool-illustration soft-green">${I('wind',36)}</span><strong>${T('Reset with breathing','শ্বাসে স্বস্তি')}</strong><small>${T('2-minute guided exercise','২ মিনিটের অনুশীলন')}</small><span>${I('arrow',17)}</span></a><a href="#/scenarios" class="tool-preview-card"><span class="tool-illustration soft-lavender">${I('book',36)}</span><strong>${T('Reflect on real situations','জীবনের পরিস্থিতি ভাবুন')}</strong><small>${T('4 interactive illustrated scenarios','৪টি পরিস্থিতি')}</small><span>${I('arrow',17)}</span></a><a href="#/challenges" class="tool-preview-card"><span class="tool-illustration soft-green">${I('check',36)}</span><strong>${T('Grow a gentle habit','একটি ভালো অভ্যাস গড়ুন')}</strong><small>${T('7-day or 14-day optional plans','৭ বা ১৪ দিনের অভ্যাস')}</small><span>${I('arrow',17)}</span></a><a href="#/diary" class="tool-preview-card"><span class="tool-illustration soft-sand">${I('calendar',36)}</span><strong>${T('Make a small journal entry','ডায়েরি লিখুন')}</strong><small>${T('Notice patterns over time','সময়ের সঙ্গে পরিবর্তন দেখুন')}</small><span>${I('arrow',17)}</span></a></div></section>`);}
const MOODINFO={anxious:{icon:'wind',color:'mood-mint',en:'Anxious',bn:'উদ্বিগ্ন',desc:'When worries feel hard to quiet.',descBn:'যখন দুশ্চিন্তা থামানো কঠিন।'},depressed:{icon:'cloud',color:'mood-lilac',en:'Depressed',bn:'মন খারাপ',desc:'When interest or energy feels low.',descBn:'যখন আগ্রহ বা শক্তি কম লাগে।'},stressed:{icon:'sun',color:'mood-peach',en:'Stressed',bn:'চাপে আছি',desc:'When responsibilities feel heavy.',descBn:'যখন দায়িত্ব খুব বেশি মনে হয়।'},confused:{icon:'help',color:'mood-blue',en:'Confused',bn:'বিভ্রান্ত',desc:'When clarity or focus feels distant.',descBn:'যখন মনোযোগ বা সিদ্ধান্ত কঠিন।'}};
function moodCards(short=false){return Object.entries(MOODINFO).map(([id,m])=>`<button class="mood-tile ${m.color}" data-action="start-assessment" data-id="${id}"><span class="mood-icon">${I(m.icon,25)}</span><strong>${T(m.en,m.bn)}</strong>${!short?`<p>${T(m.desc,m.descBn)}</p>`:''}<span class="mood-arrow">${I('arrow',17)}</span></button>`).join('');}
function moods(){if(!state.level||!state.profileReady)return profile();return shell(`${head(T('MINDFUL CHECK-IN','নিজেকে বোঝা'),T('How are you feeling today?','আজ আপনার মনের অবস্থা কেমন?'),T('Choose one feeling. We will explore it step by step with ten reflection questions and one relevant follow-up.','একটি অনুভূতি বেছে নিন। ১০টি প্রশ্ন এবং একটি প্রাসঙ্গিক অতিরিক্ত প্রশ্নের মাধ্যমে ধীরে ধীরে ভাবুন।'))}<div class="mood-page-grid">${moodCards()}</div><div class="info-strip">${I('info',18)}<p>${T('Your answers will create a response-frequency summary, not a medical diagnosis or a probability of illness. You can stop at any time.','আপনার উত্তর থেকে অনুভূতির ঘনত্বের সারাংশ তৈরি হবে, রোগনির্ণয় বা অসুস্থতার সম্ভাবনা নয়। যেকোনো সময় থামতে পারেন।')}</p></div>`);}
function contextual(type){if(state.level==='primary')return {focus:'Guardian observation',question:T('As a parent or guardian, where would additional support for your child be most helpful?','অভিভাবক হিসেবে আপনার সন্তানের কোন বিষয়ে অতিরিক্ত সহায়তা সবচেয়ে দরকার বলে মনে হয়?'),options:[T('School routine and classroom support','স্কুলের রুটিন ও ক্লাসের সহায়তা'),T('Family communication and reassurance','পরিবারের কথা ও আশ্বাস'),T('Rest, play and sleep routine','বিশ্রাম, খেলা ও ঘুমের রুটিন'),T('Talking with a qualified child professional','শিশু-বিশেষজ্ঞের সহায়তা')]};const a=state.answers[type]||[];const max=a.slice(0,5).reduce((idx,v,i,arr)=>v>(arr[idx]??-1)?i:idx,0);const focusLabel={anxious:['Worry','Future','Repeated thoughts','Physical sensations','Restlessness'],depressed:['Mood','Enjoyment','Connection','Energy','Sleep'],stressed:['Workload','Deadlines','Time','Fatigue','Irritability'],confused:['Emotions','Choices','Options','Thoughts','Attention']}[type][max];let l=state.level;const academy={primary:['school or family','স্কুল বা পরিবার'],high:['school, friendships or home','স্কুল, বন্ধু বা বাড়ি'],ug:['classes, campus or home','ক্লাস, ক্যাম্পাস বা বাড়ি'],pg:['study, responsibilities or home','পড়াশোনা, দায়িত্ব বা বাড়ি'],phd:['research, supervision or personal life','গবেষণা, সুপারভিশন বা ব্যক্তিগত জীবন']}[l]||['your day','আপনার দিন'];return {focus:focusLabel,question:T(`You reported some experiences related to ${focusLabel.toLowerCase()}. Where would you most value extra support in ${academy[0]}?`,`আপনার উত্তরে ${focusLabel} সম্পর্কিত কিছু অভিজ্ঞতার কথা এসেছে। ${academy[1]} — কোথায় সাহায্য পেলে সবচেয়ে ভালো লাগবে?`),options:[T('Organising responsibilities','দায়িত্ব গুছিয়ে নেওয়া'),T('Talking with someone I trust','বিশ্বাসী কারও সঙ্গে কথা বলা'),T('Rest and everyday routine','বিশ্রাম ও দৈনন্দিন অভ্যাস'),T('Finding professional guidance','পেশাদার সহায়তা খোঁজা')]};}
function assessment(t){if(!state.level||!state.profileReady)return profile();if(!FEELINGS[t])return moods();const f=FEELINGS[t],a=state.answers[t]||Array(10).fill(null);const step=state.step,follow=step===10,pct=Math.round(step/11*100);const question=follow?contextual(t).question:v4Question(t,step);const opts=follow?contextual(t).options:state.lang==='bn'?OPTIONS_BN:OPTIONS;const current=follow?state.contextSelections[t]:a[step];return shell(`<div class="back-row"><a href="#/moods">${I('back',16)} ${T('All feelings','অন্যান্য অনুভূতি')}</a></div><section class="assessment-frame"><div class="assess-kicker"><div>${meta(T('PERSONAL REFLECTION','ব্যক্তিগত ভাবনা'))}<h1>${esc(titleOf(t))} ${T('check-in','যাচাই')}</h1></div>${pill(T('About the last 2 weeks','গত ২ সপ্তাহ সম্পর্কে'),'soft')}</div><div class="progress-meta"><span>${T('Question','প্রশ্ন')} ${step+1} / 11</span><strong>${pct}% ${T('complete','সম্পন্ন')}</strong></div><div class="progress-rail"><span style="width:${pct}%"></span></div><form id="assessment-form" class="surface-card question-box"><span class="step-caption">${state.level==='primary'?T('GUARDIAN OBSERVATION','অভিভাবকের পর্যবেক্ষণ'):follow?T('PERSONAL FOLLOW-UP','ব্যক্তিগত অতিরিক্ত প্রশ্ন'):T('HOW OFTEN?','কতবার এমন হয়েছে?')}</span><h2>${esc(question)}</h2>${follow?`<p class="follow-note">${T('This follow-up is personalized based on your student category and earlier responses. It does not change your score.','আপনার শিক্ষার স্তর ও আগের উত্তর অনুযায়ী এই প্রশ্নটি এসেছে। এটি স্কোরে প্রভাব ফেলে না।')}</p>`:''}${state.level==='primary'?`<div class="v4-guardian-reminder">${I('shield',16)} ${T('Please answer based on what you personally observed over the last two weeks. Do not guess your child’s private thoughts.','গত দুই সপ্তাহে আপনি নিজে যা দেখেছেন, তার ভিত্তিতে উত্তর দিন। শিশুর ব্যক্তিগত চিন্তা অনুমান করবেন না।')}</div>`:''}<div class="options-list">${opts.map((opt,i)=>`<label class="answer-choice ${current===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${current===i?'checked':''} required/><span class="custom-radio"></span><span>${esc(opt)}</span>${current===i?I('check',18):''}</label>`).join('')}</div><div class="form-error" id="assess-error" role="alert"></div><div class="question-actions"><button type="button" class="btn btn-soft" data-action="prev-question">${I('back',16)} ${T('Previous','পেছনে')}</button><button type="submit" class="btn btn-solid">${step===10?T('See my summary','সারাংশ দেখুন'):T('Next question','পরের প্রশ্ন')} ${I('arrow',16)}</button></div></form><div class="assess-side-note">${I('shield',18)} ${T('Mandatory answers, private session. You may go back and edit any response.','সব প্রশ্নের উত্তর দিতে হবে। উত্তর পরিবর্তনের জন্য পেছনে যেতে পারবেন।')}</div></section>`);}
function score(t){const a=state.answers[t]||[];if(a.length!==10||a.some(v=>!Number.isInteger(v)))return null;const total=a.reduce((s,v)=>s+v,0);const pct=Math.round(total/30*100);const bands=pct<25?['Occasional','কদাচিৎ']:pct<50?['Some','কিছুদিন']:pct<75?['Frequent','ঘন ঘন']:['Very frequent','অত্যন্ত ঘন ঘন'];const group=[a.slice(0,3),a.slice(3,6),a.slice(6,10)].map(xs=>Math.round(xs.reduce((s,v)=>s+v,0)/(xs.length*3)*100));return {total,pct,band:T(...bands),group,urgent:t==='depressed'&&a[9]>0};}
const danger=()=>`<div class="urgent-box">${I('heart',19)} <div><strong>${T('Please reach out for support now','এখনই সহায়তা নিন')}</strong><p>${T('If you might hurt yourself, stay with a trusted person and contact emergency services: 112. Tele-MANAS: 14416. For children: 1098.','নিজেকে আঘাত করার ঝুঁকি থাকলে একজন বিশ্বস্ত মানুষের কাছে থাকুন এবং জরুরি নম্বর ১১২-তে যোগাযোগ করুন। টেলি-মানস: ১৪৪১৬। শিশু সহায়তা: ১০৯৮।')}</p></div></div>`;
function report(t){if(!state.profileReady)return profile();const s=score(t);if(!s||state.contextSelections[t]==null)return moods();const f=FEELINGS[t],tips=state.level==='primary'?v4ParentTips(t):f.tips;const consult=s.urgent?T('Speak with a qualified mental health professional promptly; seek emergency help if you may act on self-harm thoughts.','দ্রুত মানসিক স্বাস্থ্য বিশেষজ্ঞের সঙ্গে কথা বলুন; নিজেকে আঘাতের আশঙ্কা থাকলে জরুরি সহায়তা নিন।'):s.pct>=50?T('Arrange a conversation with a clinician or counsellor, especially if daily life is affected.','দৈনন্দিন কাজে অসুবিধা হলে চিকিৎসক বা কাউন্সেলরের সঙ্গে কথা বলুন।'):T('Consider talking with a doctor or counsellor if these experiences continue or become harder to manage.','এই অনুভূতিগুলো চলতে থাকলে বা সামলানো কঠিন হলে চিকিৎসক বা কাউন্সেলরের সঙ্গে কথা বলুন।');const ageAdvice=state.level==='primary'?'':!adult()?T(' You may also ask a parent, guardian, teacher or other trusted adult for help.',' অভিভাবক, শিক্ষক বা বিশ্বাসী কোনো বড় মানুষের সাহায্য চাইতে পারেন।'):'';return shell(`<div class="back-row"><a href="#/moods">${I('back',16)} ${T('Choose another feeling','অন্য অনুভূতি যাচাই')}</a></div><div class="report-head"><div>${meta(T('YOUR WELLBEING SUMMARY','আপনার অনুভূতির সারাংশ'))}<h1>${esc(titleOf(t))} ${T('reflection','পর্যালোচনা')}</h1><p>${esc(nameOf(state.level))} · ${fmtDate(new Date())} · ${T('Last two weeks','গত দুই সপ্তাহ')}</p></div><div class="report-buttons"><button class="btn btn-soft" data-action="print">${I('book',16)} ${T('Print','প্রিন্ট')}</button><button class="btn btn-solid" data-action="download" data-id="${t}">${I('download',16)} ${T('Download PDF','পিডিএফ নামান')}</button></div></div><section class="report-score surface-card"><div class="score-ring" style="--pct:${s.pct}"><div><strong>${s.pct}%</strong><small>${T('Response index','উত্তরের সূচক')}</small></div></div><div><span class="pill soft">${esc(s.band)} ${T('reported experiences','অভিজ্ঞতা')}</span><h2>${T('Your responses, made easier to understand.','আপনার উত্তরগুলোকে সহজভাবে বুঝুন।')}</h2><p>${T('This number represents how frequently selected experiences were reported. It is calculated from your answers (','এটি আপনার উত্তরে কত ঘন ঘন এই অভিজ্ঞতা এসেছে তা বোঝায়। হিসাব: ')}${s.total} / 30${T(' points). It is not the probability of having a disorder or an exact clinical diagnosis.',' পয়েন্ট। এটি কোনো রোগের সম্ভাবনা বা নিশ্চিত রোগনির্ণয় নয়।')}</p></div></section><div class="report-columns"><article class="surface-card detail-card"><h3>${I('chart',19)} ${T('Response pattern','উত্তরের ধরন')}</h3>${f.dimensions.map((v,i)=>`<div class="bar-row"><div><span>${esc(v)}</span><b>${s.group[i]}%</b></div><div class="bar-track"><i style="width:${s.group[i]}%"></i></div></div>`).join('')}<p class="small-muted">${T('The three groups summarize sections of the custom questionnaire. They are descriptive, not validated subscales.','এগুলো প্রশ্নগুলোর তিন ভাগের বর্ণনামূলক সারাংশ, যাচাইকৃত পৃথক স্কেল নয়।')}</p></article><article class="surface-card detail-card"><h3>${I('heart',19)} ${T('Guidance and next steps','পরামর্শ ও পরবর্তী পদক্ষেপ')}</h3><p>${esc(consult+ageAdvice)}</p><div class="medicine-note"><strong>${T('About medication','ওষুধ সম্পর্কে')}</strong><p>${T('A qualified clinician can assess whether medication or other treatment is appropriate. Do not start or stop medicines based on this score.','ওষুধ বা চিকিৎসা দরকার কি না, তা একজন যোগ্য চিকিৎসক নির্ধারণ করবেন। এই স্কোরের ভিত্তিতে ওষুধ শুরু বা বন্ধ করবেন না।')}</p></div></article></div>${s.urgent?danger():''}<section class="surface-card detail-card tips-card"><h3>${I('leaf',19)} ${T('Three gentle things you might try','আপনার জন্য তিনটি ছোট পরামর্শ')}</h3><div class="tip-grid">${tips.map((v,i)=>`<div><span>0${i+1}</span><p>${esc(v)}</p></div>`).join('')}</div><div class="report-bottom"><a href="#/support" class="btn btn-soft">${T('Explore support services','সহায়তার ঠিকানা')} ${I('arrow',16)}</a>${adult()?`<button class="btn btn-soft" data-action="save-report" data-id="${t}">${I('calendar',16)} ${state.reportSaved[t]?T('Saved to this device','ডিভাইসে সেভ হয়েছে'):T('Save to local history','লোকাল ইতিহাসে রাখুন')}</button>`:''}</div></section><div class="info-strip">${I('shield',18)}<p>${T('The report is generated entirely in your browser. Your answers are not sent to Mind-sage servers.','রিপোর্ট আপনার ব্রাউজারেই তৈরি হয়। উত্তর কোনো Mind-sage সার্ভারে পাঠানো হয় না।')}</p></div>`);}
function diary(){const entries=state.entries.filter(e=>e.kind==='mood').slice().reverse();return shell(`${head(T('A MOMENT EACH DAY','প্রতিদিন একটি মুহূর্ত'),T('Your private mood diary.','আপনার ব্যক্তিগত মুড ডায়েরি।'),T('Notice how your days change. Entries are stored only when you choose Save.','সময়ের সঙ্গে নিজের মনের অবস্থা বুঝুন। সেভ করলে তবেই এন্ট্রি রাখা হবে।'))}<div class="diary-columns"><section class="surface-card diary-form"><h3>${T('How has today felt?','আজ কেমন কাটল?')}</h3><form id="diary-form"><span class="field-caption">${T('Choose your mood','আপনার মুড বেছে নিন')}</span><div class="diary-moods">${[['calm','sun','Calm','শান্ত'],['anxious','wind','Anxious','উদ্বিগ্ন'],['stressed','cloud','Stressed','চাপে আছি'],['low','heart','Feeling low','মন খারাপ']].map(([id,i,en,bn])=>`<label class="diary-mood ${state.diaryChoice===id?'selected':''}"><input type="radio" name="mood" value="${id}" ${state.diaryChoice===id?'checked':''}/>${I(i,20)}<span>${T(en,bn)}</span></label>`).join('')}</div><label class="field"><span>${T('Energy today','আজ শক্তি কেমন?')}</span><select name="energy">${[1,2,3,4,5].map(x=>`<option value="${x}" ${state.diaryEnergy===x?'selected':''}>${x} / 5 · ${T(['','Very low','Low','Steady','Good','High'][x],['','খুব কম','কম','মাঝারি','ভালো','বেশি'][x])}</option>`).join('')}</select></label><label class="field"><span>${T('One sentence about your day (optional)','আজকের অনুভূতি (ইচ্ছামতো)')}</span><textarea name="note" maxlength="280" rows="4" placeholder="${T('Today I noticed...','আজ আমার মনে হয়েছে...')}"></textarea></label><p class="small-muted">${adult()?T('Saving creates an entry in this device’s local storage. Others using this browser profile may be able to see it.','সেভ করলে এই ব্রাউজারের লোকাল স্টোরেজে থাকবে। একই ব্রাউজার ব্যবহারকারীরা তা দেখতে পারেন।'):T('For younger students, entries remain in this session only and disappear after a page refresh. No account or research collection is enabled.','অপ্রাপ্তবয়স্কদের এন্ট্রি শুধু এই সেশনে থাকবে; রিফ্রেশ করলে হারিয়ে যাবে।')}</p><button type="submit" class="btn btn-solid btn-full">${I('check',17)} ${T(adult()?'Save privately on this device':'Keep for this session','এই সেশনে রাখুন')}</button></form></section><section class="surface-card trend-card"><h3>${T('Your recent entries','আপনার সাম্প্রতিক এন্ট্রি')}</h3>${entries.length?`<div class="trend-chart">${entries.slice(0,10).reverse().map(e=>`<div class="trend-col" title="${esc(e.mood)} · ${e.energy}/5"><i style="height:${e.energy*18}%"></i><small>${new Date(e.time).getDate()}</small></div>`).join('')}</div><p class="small-muted">${T('Bars represent self-reported energy (1–5), not symptom severity.','বারগুলিতে নিজের জানানো শক্তি (১–৫) দেখানো হয়েছে, রোগের তীব্রতা নয়।')}</p><div class="entry-list">${entries.slice(0,8).map(e=>`<div><span class="entry-dot"></span><div><strong>${esc(e.mood)}</strong><small>${fmtDate(e.time)} · ${T('Energy','শক্তি')} ${e.energy}/5</small>${e.note?`<p>${esc(e.note)}</p>`:''}</div></div>`).join('')}</div>`:`<div class="empty-diagram">${I('calendar',36)}<h4>${T('Your story starts here.','এখান থেকেই আপনার শুরু।')}</h4><p>${T('Save a small entry to see your personal pattern.','একটি এন্ট্রি সেভ করলে এখানে দেখতে পাবেন।')}</p></div>`}${entries.length?`<button class="btn btn-text danger-text" data-action="clear-diary">${I('trash',16)} ${T('Clear my saved entries','সেভ করা এন্ট্রি মুছুন')}</button>`:''}</section></div>`);}
const CHALLENGE_TASKS = [
 ['Take a 2-minute mindful breathing pause','২ মিনিট শ্বাসের ব্যায়াম করুন'],
 ['Write down one thing that went reasonably well','একটি ভালো লাগার ঘটনা লিখুন'],
 ['Take a short movement or stretching break','একটু হাঁটুন বা স্ট্রেচিং করুন'],
 ['Send a kind message to someone you trust','বিশ্বাসী কাউকে ভালো কিছু লিখুন'],
 ['Take a few minutes away from screens','কিছুক্ষণ স্ক্রিন থেকে দূরে থাকুন'],
 ['Notice five things around you using your senses','চারপাশের পাঁচটি জিনিস খেয়াল করুন'],
 ['Make space for a restful evening routine','সন্ধ্যায় বিশ্রামের সময় রাখুন'],
 ['Prepare a glass of water and enjoy it mindfully','জল খেয়ে মুহূর্তটি অনুভব করুন'],
 ['Break one task into two smaller steps','একটি কাজকে দুটি ছোট ধাপে ভাগ করুন'],
 ['Spend five minutes doing something you enjoy','পছন্দের কাজে পাঁচ মিনিট দিন'],
 ['Offer yourself one encouraging sentence','নিজেকে একটি উৎসাহের কথা বলুন'],
 ['Step outside or notice natural light if possible','সম্ভব হলে বাইরে বা প্রাকৃতিক আলোতে যান'],
 ['Talk to a friend, teacher or family member','বন্ধু, শিক্ষক বা পরিবারের কারও সঙ্গে কথা বলুন'],
 ['Reflect on which small habit helped you most','কোন ছোট অভ্যাস সবচেয়ে উপকার করেছে ভাবুন']
];
function challenges(){const c=state.challenge;const completed=c?c.days.length:0;return shell(`${head(T('SMALL HABITS, GENTLE PROGRESS','ছোট অভ্যাস, ধীর অগ্রগতি'),T('A little care, each day.','প্রতিদিন নিজের একটু যত্ন।'),T('Choose a simple 7-day or 14-day wellbeing plan. There are no streak penalties or scores; take breaks as needed.','৭ বা ১৪ দিনের সহজ পরিকল্পনা নিন। কোনো স্কোর বা প্রতিযোগিতা নেই; প্রয়োজনে বিরতি নিতে পারেন।'))}${!c?`<div class="challenge-choices">${[7,14].map(d=>`<button class="challenge-card" data-action="challenge-start" data-n="${d}"><span class="challenge-icon">${I('leaf',26)}</span><h2>${d} ${T('days','দিন')}</h2><p>${T(d===7?'A week of small mindful steps.':'Two weeks of sustainable everyday habits.',d===7?'এক সপ্তাহ ছোট অভ্যাসের অনুশীলন।':'দুই সপ্তাহ ভালো অভ্যাসের চর্চা।')}</p><b>${T('Choose this plan','এই পরিকল্পনা নিন')} ${I('arrow',16)}</b></button>`).join('')}</div>`:`<div class="surface-card challenge-active"><div class="challenge-progress-head"><div>${pill(`${c.duration}-${T('day plan','দিনের পরিকল্পনা')}`,'soft')}<h2>${completed} / ${c.duration} ${T('days completed','দিন সম্পন্ন')}</h2><p>${T('Choose a day when you are ready. You can tick a day only once and take as long as you need.','ইচ্ছামতো দিনে সম্পন্ন করুন। তাড়াহুড়ো করার প্রয়োজন নেই।')}</p></div><div class="challenge-count">${Math.round(completed/c.duration*100)}%</div></div><div class="challenge-progress-rail"><i style="width:${completed/c.duration*100}%"></i></div><div class="challenge-days">${CHALLENGE_TASKS.slice(0,c.duration).map((x,i)=>`<button class="challenge-day ${c.days.includes(i)?'complete':''}" data-action="challenge-day" data-n="${i}" ${c.days.includes(i)?'disabled':''}><span>${c.days.includes(i)?I('check',20):String(i+1).padStart(2,'0')}</span><div><small>${T('DAY','দিন')} ${i+1}</small><strong>${T(...x)}</strong></div>${I('chevron',18)}</button>`).join('')}</div><button data-action="challenge-clear" class="btn btn-text danger-text">${I('refresh',16)} ${T('Choose a different plan','অন্য পরিকল্পনা নিন')}</button></div>`}<div class="info-strip">${I('shield',18)}<p>${adult()?T('This optional plan is saved on your device. You can remove it at any time.','এই পরিকল্পনা ডিভাইসে সেভ হবে। ইচ্ছা হলে মুছতে পারবেন।'):T('For younger students, challenge progress stays in this session only.','অপ্রাপ্তবয়স্কদের অগ্রগতি শুধু সেশনে থাকবে।')}</p></div>`);}
function saveChallenge(){if(adult())try{localStorage.setItem('mindsage_v4_challenge',JSON.stringify(state.challenge));}catch(err){/* session-only fallback */}}
function illustration(id){const scenes={exam:'<div class="scene-desk"><div class="scene-notebook"><i></i><i></i><i></i></div><div class="scene-cup"></div><div class="scene-clock">10:15</div></div><span class="scene-sun">✳</span>',social:'<div class="scene-social"><span></span><span></span><span></span><span></span></div><div class="scene-bench"></div><span class="scene-sun">✺</span>',deadline:'<div class="scene-papers"><span>MON</span><span>TUE</span><span>WED</span></div><div class="scene-pencil"></div><span class="scene-sun">✦</span>',rest:'<div class="scene-window"><span class="window-sun"></span></div><div class="scene-plant"><i></i><i></i><i></i></div><span class="scene-cup"></span>'};return `<div class="scene-art scene-${id}" aria-hidden="true">${scenes[id]}</div>`;}
function scenarios(){return shell(`${head(T('REFLECT & RESPOND','ভাবুন ও উত্তর দিন'),T('Explore everyday moments.','পরিচিত কিছু মুহূর্তকে নতুনভাবে ভাবুন।'),T('Picture yourself in each situation and choose a helpful response. These are reflection exercises, not a psychological test.','পরিস্থিতিগুলো কল্পনা করুন এবং নিজের পছন্দের উত্তর দিন। এগুলো ভাবনার অনুশীলন, মনস্তাত্ত্বিক পরীক্ষা নয়।'))}<div class="scenario-grid">${SCENARIOS.map(s=>`<a class="scenario-card" href="#/scenario/${s.id}">${illustration(s.art)}<div class="scenario-info">${meta(T(s.tag,s.bnTag))}<h3>${esc(T(s.title,s.bnTitle))}</h3><p>${esc(T(s.desc,s.bnDesc))}</p><span>${T('Explore situation','পরিস্থিতিটি দেখুন')} ${I('arrow',16)}</span></div></a>`).join('')}</div>`);}
function scenario(id){const s=SCENARIOS.find(x=>x.id===id);if(!s)return scenarios();const selected=state.scenarioChoice[id];return shell(`<div class="back-row"><a href="#/scenarios">${I('back',16)} ${T('All scenarios','সব পরিস্থিতি')}</a></div><div class="scenario-detail"><section>${illustration(s.art)}<div class="scenario-detail-copy">${meta(T(s.tag,s.bnTag))}<h1>${T(s.title,s.bnTitle)}</h1><p>${T(s.desc,s.bnDesc)}</p></div></section><section class="surface-card scenario-question"><span class="step-caption">${T('A MOMENT TO REFLECT','একটু ভাবুন')}</span><h2>${T(s.question,s.bnQuestion)}</h2><div class="options-list">${s.options.map((v,i)=>`<button class="answer-choice scene-answer ${selected===i?'selected':''}" data-action="scenario-choice" data-id="${id}" data-n="${i}">${I(selected===i?'check':'arrow',17)} <span>${T(v,s.bnOptions[i])}</span></button>`).join('')}</div>${selected!=null?`<div class="tip-note">${I('spark',20)} <p>${T(s.note,s.bnNote)}</p></div>`:''}<div class="question-actions">${cta('scenarios',T('Another scenario','আরেকটি পরিস্থিতি'),true)}${cta('bromind',T('Try a calm exercise','শান্ত থাকার অনুশীলন'))}</div></section></div>`);}
function broMind(){return shell(`<section class="calm-hero"><div>${pill('BRO-MIND PLUS','light')}<h1>${T('A little stillness,<br><em>whenever you need it.</em>','যখনই দরকার,<br><em>একটু শান্তি খুঁজুন।</em>')}</h1><p>${T('Breathe, focus, rest, and read words that gently encourage.','শ্বাসের ব্যায়াম, মনোযোগ, বিশ্রাম ও অনুপ্রেরণার কথা।')}</p></div><div class="calm-flower">✺</div></section><div class="bro-grid">${TOOLS.map(o=>`<a class="bro-card" href="#/${o.id}"><span class="tool-big-icon">${I(o.icon,28)}</span><h3>${T(o.title,o.bn)}</h3><p>${T(o.description,{'breathing':'দুই মিনিটের শান্ত শ্বাসের অনুশীলন।','grounding':'পাঁচ ইন্দ্রিয় দিয়ে চারপাশে মনোযোগ।','meditation':'তিন মিনিটের ধ্যান।','vani':'স্বামী বিবেকানন্দের বাংলা বাণী।','motivation':'দিনের জন্য কিছু আন্তরিক কথা।'}[o.id])}</p><b>${T('Begin','শুরু করুন')} ${I('arrow',16)}</b></a>`).join('')}</div>`);}
function timerPage(mode){const breath=mode==='breathing',total=breath?120:180;const h=breath?T('Let your breath find its rhythm.','শ্বাসের ছন্দে শান্তি খুঁজুন।'):T('Give yourself a quiet moment.','নিজেকে একটু শান্ত সময় দিন।');return shell(`<div class="back-row"><a href="#/bromind">${I('back',16)} ${T('Bro-minD Plus','ব্রো-মিন্ড প্লাস')}</a></div><section class="exercise-shell">${meta(breath?T('2-MINUTE BREATHING','২ মিনিটের শ্বাসের ব্যায়াম'):T('3-MINUTE MEDITATION','৩ মিনিটের ধ্যান'))}<h1>${h}</h1><p>${breath?T('Gently breathe in for 4 seconds, pause for 2, and breathe out for 6. If the pause feels uncomfortable, return to your natural breathing.','৪ সেকেন্ড শ্বাস নিন, ২ সেকেন্ড থামুন, ৬ সেকেন্ডে ছাড়ুন। অস্বস্তি হলে স্বাভাবিকভাবে শ্বাস নিন।'):T('Sit in a comfortable position. Gently notice your posture, breathing and surroundings without judging your thoughts.','আরাম করে বসুন। নিজের ভঙ্গি, শ্বাস ও চারপাশে মন দিন। চিন্তা এলে নিজেকে দোষ দেবেন না।')}</p>${breath?`<div class="breath-orbit" id="breath-orbit"><div><strong id="breath-label">${T('Ready','প্রস্তুত')}</strong><small id="breath-sub">${T('At your pace','নিজের গতিতে')}</small></div></div>`:`<div class="meditation-art"><span>◌</span><div id="meditation-phase">${T('Settle into your seat.','আরাম করে বসুন।')}</div></div>`}<div id="countdown" class="countdown">0${Math.floor(total/60)}:00</div><div class="exercise-controls"><button class="btn btn-solid" data-action="timer-toggle" data-mode="${mode}" id="timer-toggle">${I('play',17)} ${T('Start session','শুরু করুন')}</button><button class="btn btn-soft" data-action="timer-reset" data-mode="${mode}">${I('refresh',17)} ${T('Reset','আবার শুরু')}</button>${!breath?`<button class="btn btn-soft" data-action="meditation-speak">${I('volume',17)} ${T('Listen to guidance','নির্দেশনা শুনুন')}</button>`:''}</div><p class="small-muted align-center">${T('You can stop whenever you wish. If you feel dizzy or uncomfortable, return to ordinary breathing.','ইচ্ছা হলে থামতে পারেন। মাথা ঘুরলে বা অস্বস্তি হলে স্বাভাবিক শ্বাসে ফিরে আসুন।')}</p></section>`);}
function grounding(){return shell(`<div class="back-row"><a href="#/bromind">${I('back',16)} Bro-minD Plus</a></div>${head(T('GENTLE GROUNDING','মনোযোগ ফিরিয়ে আনুন'),T('Find your way back to now.','ফিরে আসুন এই মুহূর্তে।'),T('Use your five senses to notice what is around you. Check each step whenever you are ready.','পাঁচ ইন্দ্রিয় দিয়ে চারপাশকে লক্ষ করুন। প্রতিটি ধাপ শেষে টিক দিন।'))}<div class="ground-card surface-card">${[[5,'things you can see','যা দেখতে পাচ্ছেন'],[4,'things you can feel','যা অনুভব করতে পারছেন'],[3,'things you can hear','যা শুনতে পাচ্ছেন'],[2,'things you can smell','যা গন্ধ পাচ্ছেন'],[1,'thing you can taste','যা স্বাদ নিতে পারছেন']].map(([n,en,bn],i)=>`<label class="ground-row ${state.focusChecks[i]?'complete':''}"><input type="checkbox" data-focus="${i}" ${state.focusChecks[i]?'checked':''}/><span class="ground-number">${n}</span><span>${T(en,bn)}</span>${I(state.focusChecks[i]?'check':'target',19)}</label>`).join('')}<div class="ground-finish">${state.focusChecks.filter(Boolean).length} / 5 ${T('steps complete','ধাপ সম্পন্ন')}${state.focusChecks.every(Boolean)?` · ${T('Well done. Take a comfortable breath.','দারুণ। এবার আরাম করে শ্বাস নিন।')}`:''}</div><button class="btn btn-soft" data-action="ground-reset">${I('refresh',16)} ${T('Start again','আবার শুরু করুন')}</button></div>`);}
function vani(){const q=QUOTES[state.quoteIndex];return shell(`<div class="back-row"><a href="#/bromind">${I('back',16)} Bro-minD Plus</a></div><div class="vani-hero"><div class="vani-overlay">${meta('স্বামীজীর বাণী · VANI')}<h1>${T('Wisdom that stays with us.','স্বামীজীর অমৃতবাণী।')}</h1><blockquote lang="bn">“${esc(q.bn)}”</blockquote><p>স্বামী বিবেকানন্দ · ${esc(q.source)}</p><a class="vani-link" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${T('Read original at Belur Math','বেলুড় মঠের উৎস পড়ুন')} ${I('arrow',16)}</a><div class="vani-nav"><button class="btn btn-light" data-action="quote-prev">${I('back',16)} ${T('Previous','আগের')}</button><button class="btn btn-light" data-action="quote-next">${T('Next saying','পরের বাণী')} ${I('arrow',16)}</button><span>${state.quoteIndex+1} / ${QUOTES.length}</span></div></div></div><div class="section-space"><div class="section-heading"><h2>${T('The Vani collection','বাণী সংগ্রহ')}</h2><p>${T('Each Bengali passage links to a Belur Math source. The portrait is an artistic illustration.','প্রতিটি বাণীর সঙ্গে বেলুড় মঠের উৎস রয়েছে। ছবিটি শিল্পিত প্রতিকৃতি।')}</p></div><div class="quotes-grid">${QUOTES.map((v,i)=>`<button class="quote-card ${i===state.quoteIndex?'selected':''}" data-action="quote-select" data-n="${i}"><span>0${i+1}</span><p lang="bn">${esc(v.bn)}</p>${I('arrow',16)}</button>`).join('')}</div></div>`);}
function motivation(){return shell(`${head(T('WORDS FOR YOUR DAY','আজকের জন্য কিছু কথা'),T('A little encouragement matters.','একটু উৎসাহও মূল্যবান।'),T('Short, original reflections for your own wellbeing and growth.','নিজের যত্ন ও এগিয়ে যাওয়ার জন্য কিছু মৌলিক অনুপ্রেরণামূলক কথা।'))}<div class="motivation-grid">${MOTIVATIONS.map((v,i)=>`<article class="motivation-card"><span class="motivation-serial">0${i+1} · ${T('REFLECTION','ভাবনা')}</span><h3>${esc(T(v.title,['অগ্রগতি সবসময় চোখে পড়ে না','আবার শুরু করা যায়','আপনার গতি আপনার নিজের','সম্পর্কই শক্তি','বিশ্রামও পরিকল্পনার অংশ','গুরুত্বপূর্ণ বিষয়গুলোকে সময় দিন'][i]))}</h3><p>${esc(T(v.text,['সব ভালো পরিবর্তন একদিনে ধরা পড়ে না। কখনও একটি ছোট কাজ শেষ করা, সাহায্য চাওয়া কিংবা কঠিন দিনে চেষ্টা করাও অগ্রগতি।','একটি কঠিন সকাল গোটা দিনটাকে নির্ধারণ করে না। পরিস্থিতি বুঝে ছোট একটি কাজ দিয়ে আবার শুরু করুন।','অন্যের সঙ্গে তুলনা না করে নিজের শেখা ও পথচলার দিকে নজর দিন। সুস্থভাবে এগিয়ে যাওয়ার গতিই আপনার জন্য ভালো।','সব কঠিন সমস্যার সমাধান একা করতে হয় না। কাছের মানুষ, শিক্ষক বা কাউন্সেলরের সঙ্গে কথা বলা শক্তির লক্ষণ।','নিজের মনোযোগ ও শক্তি ফিরিয়ে আনতে বিশ্রাম জরুরি। ক্লান্তির শেষ সীমায় না পৌঁছেও বিরতি নিতে পারেন।','সবকিছু জরুরি মনে হলে আজকের সত্যিকারের গুরুত্বপূর্ণ কাজটি বেছে নিন। ছোট পদক্ষেপ থেকেই স্বচ্ছতা আসে।'][i]))}</p></article>`).join('')}</div>`);}
const RESOURCES=[
 {name:'Tele-MANAS',type:'Mental health helpline',bn:'মানসিক স্বাস্থ্য সহায়তা',number:'14416',detail:'24-hour government tele-mental-health support.',bnDetail:'ভারত সরকারের ২৪ ঘণ্টার মানসিক স্বাস্থ্য সহায়তা।',url:'https://dghs.mohfw.gov.in/national-mental-health-programme.php',icon:'heart'},
 {name:'District Mental Health Programme',type:'Public mental health services',bn:'জেলার সরকারি মানসিক স্বাস্থ্যসেবা',number:'District hospital',detail:'District-level counselling and referral services.',bnDetail:'জেলা হাসপাতালে পরামর্শ ও রেফারেল সেবা।',url:'https://dghs.mohfw.gov.in/national-mental-health-programme.php',icon:'users'},
 {name:'KIRAN',type:'Mental health support',bn:'মানসিক স্বাস্থ্য সহায়তা',number:'1800-599-0019',detail:'Listed by the Department of Empowerment of Persons with Disabilities.',bnDetail:'প্রতিবন্ধী ব্যক্তিদের ক্ষমতায়ন বিভাগের তালিকাভুক্ত হেল্পলাইন।',url:'https://depwd.gov.in/en/others-helplines/',icon:'heart'},
 {name:'Child Helpline',type:'Child protection support',bn:'শিশু সহায়তা',number:'1098',detail:'For children needing support and protection.',bnDetail:'সহায়তা ও সুরক্ষা প্রয়োজন এমন শিশুদের জন্য।',url:'https://www.childlineindia.org/',icon:'users'},
 {name:'National emergency response',type:'Urgent emergencies',bn:'জরুরি পরিষেবা',number:'112',detail:'Emergency assistance in India.',bnDetail:'ভারতে জরুরি পরিষেবা।',url:'https://112.gov.in/',icon:'shield'},
 {name:'National Anti-Ragging Helpline',type:'Student protection',bn:'র‍্যাগিং বিরোধী সহায়তা',number:'1800-180-5522',detail:'Government-listed student anti-ragging helpline.',bnDetail:'শিক্ষার্থীদের র‍্যাগিং সংক্রান্ত সাহায্যের নম্বর।',url:'https://www.antiragging.in/',icon:'users'}
];
function support(){return shell(`${head(T('REAL HELP, REAL CONNECTIONS','বাস্তব সহায়তার ঠিকানা'),T('Support is within reach.','সহায়তা পাওয়া সম্ভব।'),T('Government and public support services in India, with links to their official pages.','ভারতের সরকারি ও জনসেবামূলক সহায়তার নম্বর ও সরকারি উৎস।'))}<div class="support-spotlight"><div>${I('heart',25)}<h2>${T('Need someone to talk to?','কারও সঙ্গে কথা বলতে চান?')}</h2><p>${T('Tele-MANAS offers 24-hour mental health tele-support across India.','টেলি-মানস ভারতে ২৪ ঘণ্টার মানসিক স্বাস্থ্য সহায়তা দেয়।')}</p></div><a href="tel:14416" class="support-number">14416 ${I('arrow',22)}</a></div><div class="support-list">${RESOURCES.map(r=>`<article class="support-entry"><span class="support-entry-icon">${I(r.icon,22)}</span><div>${meta(T(r.type,r.bn))}<h3>${esc(r.name)}</h3><p>${T(r.detail,r.bnDetail)}</p><a href="${r.url}" rel="noopener noreferrer" target="_blank">${T('Official information','সরকারি তথ্য')} ${I('arrow',15)}</a></div><a href="${/^\d[\d-]+$/.test(r.number)?'tel:'+r.number.replace(/-/g,''):r.url}" class="number-pill">${esc(r.number)}</a></article>`).join('')}</div><div class="info-strip">${I('info',18)}<p>${T('Helpline availability and programme details may change. Verify current information on the linked official pages.','হেল্পলাইনের সময় ও কর্মসূচি বদলাতে পারে। সরকারি উৎস থেকে বর্তমান তথ্য যাচাই করুন।')}</p></div>`);}
function companion(){return shell(`${head(T('GUIDED WELLBEING COMPANION','পরামর্শের সহযাত্রী'),T('A thoughtful conversation.','একটু কথা বলা যাক।'),T('A private, rule-based guide to exercises and support information. It works entirely in your browser.','শ্বাসের ব্যায়াম, মনোযোগ ও সহায়তার তথ্য দেওয়ার একটি ব্রাউজারভিত্তিক নির্দেশিত সহায়ক।'))}<div class="chat-layout"><div class="surface-card chat-card"><div class="chat-title"><div class="chat-avatar">${I('leaf',22)}</div><div><strong>Mind-sage Companion</strong><small>${T('On-device guided responses','ডিভাইসেই নির্ধারিত উত্তর')}</small></div><span class="offline-indicator">${T('LOCAL','লোকাল')}</span></div><div class="chat-messages" id="chat-messages" aria-live="polite">${state.companion.map(m=>`<div class="chat-bubble ${m.who==='user'?'mine':'theirs'}">${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="chat-input-row"><input name="message" maxlength="500" autocomplete="off" placeholder="${T('Type a few words...','কিছু লিখুন...')}" required/><button type="submit" class="btn btn-solid" aria-label="Send">${I('arrow',18)}</button></form></div><aside class="chat-side"><div class="surface-card"><h3>${T('Choose a starting point','কোথা থেকে শুরু করবেন?')}</h3><div class="chat-suggestions">${[['anxious','I feel worried','আমি উদ্বিগ্ন'],['stressed','I feel overwhelmed by studies','পড়াশোনায় চাপ হচ্ছে'],['sleep','I cannot sleep well','ঘুম ভালো হচ্ছে না'],['support','I would like to find support','আমি সহায়তা চাই']].map(([id,en,bn])=>`<button data-action="chat-preset" data-id="${id}">${T(en,bn)} ${I('arrow',15)}</button>`).join('')}</div></div><div class="chat-note">${I('shield',21)}<p>${T('Messages are not uploaded or stored. This is a guided-response companion, not a live human counsellor or an AI chat service.','বার্তা আপলোড বা সেভ হয় না। এটি নির্ধারিত উত্তরের সহায়ক, মানব কাউন্সেলর বা AI চ্যাট নয়।')}</p><a href="#/support">${T('Find real-world support','বাস্তব সহায়তা খুঁজুন')}</a></div></aside></div>`);}
function researcher(){const reportEntries=state.entries.filter(e=>e.kind==='report');const moodEntries=state.entries.filter(e=>e.kind==='mood');const avg=reportEntries.length?Math.round(reportEntries.reduce((n,e)=>n+e.pct,0)/reportEntries.length):null;const allowed=adult();return shell(`${head(T('ON-DEVICE INSIGHTS','এই ডিভাইসের তথ্য'),T('Reflect on your patterns.','নিজের অভ্যাস ও অনুভূতি দেখুন।'),T('This is a local, opt-in personal summary and export tool. It is not a university-wide research database or a clinical analytics dashboard.','এটি শুধু এই ডিভাইসের ব্যক্তিগত সারাংশ ও ডেটা এক্সপোর্টের ব্যবস্থা। এটি বিশ্ববিদ্যালয়ের গবেষণা ডাটাবেস নয়।'))}<div class="insight-grid"><div class="insight-stat">${I('calendar',25)}<small>${T('Mood entries','মুড এন্ট্রি')}</small><strong>${moodEntries.length}</strong></div><div class="insight-stat">${I('heart',25)}<small>${T('Saved reports','সেভ করা রিপোর্ট')}</small><strong>${reportEntries.length}</strong></div><div class="insight-stat">${I('chart',25)}<small>${T('Mean saved response index','গড় সেভ করা স্কোর')}</small><strong>${avg==null?'—':avg+'%'}</strong></div></div><div class="research-layout"><section class="surface-card detail-card"><h3>${T('Optional personal data export','নিজের তথ্য এক্সপোর্ট করুন')}</h3><p>${T('The export includes only your saved mood/assessment summaries, not your date of birth, gender, free-text diary notes or assessment item-level answers. It will never combine data from other users.','এক্সপোর্টে সেভ করা মুড/মূল্যায়নের সারাংশ থাকবে। জন্মতারিখ, লিঙ্গ, ডায়েরির ব্যক্তিগত লেখা বা প্রতিটি প্রশ্নের উত্তর থাকবে না। অন্য কারও তথ্য যুক্ত হবে না।')}</p>${allowed?`<label class="consent-line"><input type="checkbox" id="export-consent"/> <span>${T('I understand this export will save my data as a file on this device.','আমি বুঝেছি, এক্সপোর্ট করলে আমার তথ্য এই ডিভাইসে ফাইল হয়ে থাকবে।')}</span></label><button class="btn btn-solid" data-action="export-data">${I('download',17)} ${T('Export my CSV','আমার CSV নামান')}</button>`:`<div class="info-strip compact-strip">${I('shield',18)}<p>${T('Research-data export is reserved for adults. For younger students, this feature remains unavailable without appropriate approved consent arrangements.','যথাযথ অনুমোদিত সম্মতি ছাড়া অপ্রাপ্তবয়স্কদের গবেষণা ডেটা এক্সপোর্ট বন্ধ রাখা হয়েছে।')}</p></div>`}</section><section class="surface-card detail-card"><h3>${T('For a future university study','ভবিষ্যৎ বিশ্ববিদ্যালয় গবেষণা')}</h3><p>${T('A formal research portal would need institutional ethics review, explicit consent, secure authentication, encrypted data storage, a withdrawal mechanism and appropriate safeguarding before collecting participant records.','গবেষণায় অংশগ্রহণকারীর তথ্য সংগ্রহের আগে নৈতিক অনুমোদন, স্পষ্ট সম্মতি, নিরাপদ লগইন, এনক্রিপ্টেড ডেটা সংরক্ষণ, সম্মতি প্রত্যাহার এবং সুরক্ষার ব্যবস্থা জরুরি।')}</p><a class="inline-link" href="#/privacy">${T('See data handling details','তথ্যের গোপনীয়তা দেখুন')} ${I('arrow',16)}</a></section></div>`);}
function privacy(){return shell(`${head(T('PRIVACY & TRANSPARENCY','গোপনীয়তা ও স্বচ্ছতা'),T('Your information stays in your hands.','আপনার তথ্যের নিয়ন্ত্রণ আপনার হাতে।'),T('How the static GitHub Pages version of Mind-sage handles information.','GitHub Pages-এ চলা Mind-sage কীভাবে তথ্য ব্যবহার করে।'))}<div class="privacy-grid">${[
 ['lock','Assessment answers','Questionnaire answers, date of birth and gender remain in JavaScript memory during this browser tab session. The website has no API endpoint or database that receives them.','প্রশ্নের উত্তর, জন্মতারিখ ও লিঙ্গ ট্যাবের এই সেশনের মেমোরিতে থাকে।'],
 ['calendar','Mood diary','Adults can explicitly save diary entries and report summaries in browser localStorage. Children’s entries are in memory only. Users sharing a device/browser profile may see saved adult entries.','প্রাপ্তবয়স্করা চাইলে লোকাল স্টোরেজে ডায়েরি রাখতে পারেন। শিশুদের এন্ট্রি সেশনেই থাকে।'],
 ['shield','Controls and deletion','Clear saved entries from the diary. You can also clear browser site data. Downloaded PDFs and CSV files must be deleted separately from your device.','ডায়েরি থেকে সেভ করা তথ্য মুছুন। ডাউনলোড করা PDF/CSV আলাদাভাবে মুছতে হবে।'],
 ['info','Important limits','An arithmetic captcha does not provide server-side bot protection. This site does not have clinical validation, authenticated accounts, central records or an AI model.','এই সাইটে সার্ভারভিত্তিক ক্যাপচা, যাচাইকৃত রোগনির্ণয়, অ্যাকাউন্ট, কেন্দ্রীয় রেকর্ড বা AI মডেল নেই।']
 ].map(([i,en,desc,bn])=>`<article class="surface-card detail-card"><h3>${I(i,19)} ${T(en,bn.split('।')[0])}</h3><p>${T(desc,bn)}</p></article>`).join('')}</div>`);}
function navigation(){stopTimer();const parts=location.hash.replace(/^#\/?/,'').split('/'),page=(parts[0]||'home').toLowerCase();document.title=`Mind-sage V4 | ${page==='home'?'Student wellbeing':page}`;window.scrollTo({top:0,behavior:'instant'});let html;
 switch(page){case 'home':html=v3Landing();break;case 'profile':html=profile();break;case 'dashboard':html=v3Dashboard();break;case 'moods':html=moods();break;case 'assessment':html=assessment(parts[1]);break;case 'report':html=report(parts[1]);break;case 'diary':html=diary();break;case 'challenges':html=challenges();break;case 'scenarios':html=scenarios();break;case 'scenario':html=scenario(parts[1]);break;case 'videos':html=v4VideoLibrary();break;case 'bromind':html=broMind();break;case 'breathing':html=timerPage('breathing');break;case 'meditation':html=timerPage('meditation');break;case 'grounding':html=grounding();break;case 'vani':html=vani();break;case 'motivation':html=motivation();break;case 'support':html=support();break;case 'companion':html=companion();break;case 'research':html=researcher();break;case 'privacy':html=privacy();break;case 'landscape':html=v3Landscape();break;case 'garden':html=v3Garden();break;case 'journey':html=v3Journey(parts[1]);break;case 'journal':html=v3Journal();break;case 'plan':html=v3Plan();break;case 'insights':html=v3Insights();break;case 'mindmap':html=v3MindMap();break;case 'relaxation':html=v3Relaxation();break;case 'access':html=v3Access();break;case 'connect':html=v3Connect();break;default:html=landing();}
 if(typeof html==='string')root.innerHTML=html;
 if(typeof v3AfterNavigate === 'function')v3AfterNavigate(page);
 if(page==='companion'){const el=document.querySelector('#chat-messages');if(el)el.scrollTop=el.scrollHeight;}
}
const render=navigation;
function stopTimer(){if(state.timer){if(!state.timerPaused){state.timerMs+=performance.now()-state.timerStarted;state.timerPaused=true;}clearInterval(state.timer);state.timer=null;}if('speechSynthesis' in window)window.speechSynthesis.cancel();}
function appendEntry(entry){state.entries.push(entry);if(adult()){try{const persistent=state.entries.filter(x=>x.stored);localStorage.setItem(NS,JSON.stringify(persistent.slice(-120)));}catch(err){alert(T('Your device could not save this entry. Please check browser storage settings.','ব্রাউজারে সেভ করা যায়নি। সেটিংস দেখুন।'));return false;}}return true;}
function loadEntries(){if(!adult())return;try{const a=JSON.parse(localStorage.getItem(NS)||'[]');if(Array.isArray(a))state.entries=a.filter(x=>x&&['mood','report'].includes(x.kind)&&typeof x.time==='string').slice(-120);}catch(e){state.entries=[];}}
function chatReply(msg){const t=msg.toLowerCase();const urgent=/suicid|kill myself|self.harm|hurt myself|end my life|মরে যেতে|আত্মহত্যা|নিজেকে আঘাত|বাঁচতে চাই না/.test(t);if(urgent)return T('I am concerned about your safety. Please tell someone you trust and seek immediate human support. If you might act on these thoughts, call 112 now. Tele-MANAS: 14416; Child Helpline: 1098.','আপনার নিরাপত্তা গুরুত্বপূর্ণ। এখনই বিশ্বাসী কাউকে জানান। নিজেকে আঘাত করার আশঙ্কা থাকলে ১১২-তে ফোন করুন। টেলি-মানস: ১৪৪১৬; শিশু সহায়তা: ১০৯৮।');if(/anx|worr|panic|ভয়|দুশ্চিন্তা|উদ্বিগ্ন/.test(t))return T('Worry can feel exhausting. Try noticing your feet on the floor and taking a gentle, comfortable breath. You can visit Bro-minD for a short breathing practice. If worry keeps affecting your day, consider a counsellor.','দুশ্চিন্তা ক্লান্তিকর হতে পারে। পা মাটিতে রাখুন, আরাম করে শ্বাস নিন। ব্রো-মিন্ডে শ্বাসের ব্যায়াম করতে পারেন। সমস্যা চললে কাউন্সেলরের সাহায্য নিন।');if(/exam|study|research|deadlin|pressure|stress|কাজ|পরীক্ষা|পড়াশোনা|চাপ/.test(t))return T('When everything feels urgent, write down just three tasks and choose one manageable next step. You can also talk to a teacher, supervisor or trusted person about the workload.','সব কাজ জরুরি মনে হলে তিনটি কাজ লিখে একটি ছোট কাজ দিয়ে শুরু করুন। শিক্ষক, সুপারভাইজার বা কাছের কারও সঙ্গে কথা বলতে পারেন।');if(/sleep|tired|insomnia|ঘুম|ক্লান্ত/.test(t))return T('A steady bedtime, less screen time before sleep, and a calm wind-down may help. If sleep difficulties persist, speak with a health professional.','নিয়মিত ঘুমের সময়, রাতে কম স্ক্রিন ব্যবহার এবং কিছুক্ষণ শান্ত থাকা সহায়ক হতে পারে। সমস্যা চললে চিকিৎসকের সঙ্গে কথা বলুন।');if(/alone|sad|lonely|depress|মন খারাপ|একা|দুঃখ/.test(t))return T('It can help to share how you feel with a person you trust. A small nourishing activity and some rest may also be useful. If low mood is ongoing or severe, contact a qualified mental health professional.','বিশ্বাসী মানুষের সঙ্গে কথা বলুন। বিশ্রাম বা মন ভালো করে এমন ছোট কাজে সময় দিতে পারেন। মন খারাপ দীর্ঘস্থায়ী হলে বিশেষজ্ঞের সাহায্য নিন।');if(/help|support|doctor|counsell|সহায়তা|ডাক্তার/.test(t))return T('You can open the Support Directory for verified options. In India, Tele-MANAS is available at 14416, and 112 is the emergency number.','সহায়তার ঠিকানা পাতায় তথ্য পাবেন। ভারতে টেলি-মানস ১৪৪১৬ এবং জরুরি পরিষেবা ১১২।');return T('Thank you for sharing. I may not understand every detail, but we can take one small step: notice how you feel, try a grounding pause, or speak with someone you trust. Choose a suggested topic or explore the support directory.','আপনার কথা বলার জন্য ধন্যবাদ। সবকিছু বুঝতে না পারলেও আমরা একটি ছোট পদক্ষেপ নিতে পারি: অনুভূতি খেয়াল করুন, একটু থামুন বা বিশ্বাসী কারও সঙ্গে কথা বলুন।');}
function chatSend(msg){const text=msg.trim();if(!text)return;state.companion.push({who:'user',text:text.slice(0,500)});state.companion.push({who:'bot',text:chatReply(text)});render();}
function handleClick(e){const navbutton=e.target.closest('#menu-toggle');if(navbutton){const shell=document.querySelector('.app-shell');const open=shell.classList.toggle('nav-open');navbutton.setAttribute('aria-expanded',String(open));return;}if(e.target.closest('#nav-shade')){document.querySelector('.app-shell')?.classList.remove('nav-open');return;}const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;
 if(act==='lang'){state.lang=state.lang==='en'?'bn':'en';render();}
 else if(act==='level'){state.level=el.dataset.id;state.dob='';state.gender='';state.age=null;state.entries=[];state.profileReady=false;state.guardianRelationship='';state.answers={};state.contextSelections={};state.reportSaved={};state.step=0;generateCaptcha();go('profile');}
 else if(act==='captcha'){generateCaptcha();render();}
 else if(act==='start-assessment'){state.type=el.dataset.id;state.step=0;state.answers[state.type]=Array(10).fill(null);delete state.contextSelections[state.type];delete state.reportSaved[state.type];go('assessment/'+state.type);}
 else if(act==='prev-question'){if(state.step>0){state.step--;render();}else go('moods');}
 else if(act==='scenario-choice'){state.scenarioChoice[el.dataset.id]=Number(el.dataset.n);render();}
 else if(act==='challenge-start'){state.challenge={duration:Number(el.dataset.n),days:[]};saveChallenge();render();}
 else if(act==='challenge-day'){if(!state.challenge)return;const n=Number(el.dataset.n);if(!state.challenge.days.includes(n)&&n>=0&&n<state.challenge.duration){state.challenge.days.push(n);saveChallenge();render();}}
 else if(act==='challenge-clear'){if(confirm(T('Reset your current gentle-habit plan?','বর্তমান অভ্যাসের পরিকল্পনা নতুন করে শুরু করবেন?'))){state.challenge=null;if(adult())localStorage.removeItem('mindsage_v4_challenge');render();}}
 else if(act==='ground-reset'){state.focusChecks=state.focusChecks.map(()=>false);render();}
 else if(act==='quote-prev'){state.quoteIndex=(state.quoteIndex-1+QUOTES.length)%QUOTES.length;render();}
 else if(act==='quote-next'){state.quoteIndex=(state.quoteIndex+1)%QUOTES.length;render();}
 else if(act==='quote-select'){state.quoteIndex=Number(el.dataset.n);render();}
 else if(act==='clear-diary'){if(confirm(T('Delete all private diary and saved report entries on this device?','এই ডিভাইসের সমস্ত সেভ করা ডায়েরি ও রিপোর্ট মুছবেন?'))){state.entries=[];state.reportSaved={};localStorage.removeItem(NS);render();}}
 else if(act==='save-report'){if(!adult())return;const t=el.dataset.id,s=score(t);if(!s)return;if(state.reportSaved[t])return;const ok=appendEntry({kind:'report',type:t,pct:s.pct,time:new Date().toISOString(),stored:true,level:state.level});if(ok){state.reportSaved[t]=true;render();}}
 else if(act==='print')window.print();
 else if(act==='download')downloadPDF(el.dataset.id);
 else if(act==='chat-preset'){chatSend(({anxious:T('I feel worried','আমি উদ্বিগ্ন'),stressed:T('I feel overwhelmed by studies','পড়াশোনায় চাপ হচ্ছে'),sleep:T('I cannot sleep well','ঘুম ভালো হচ্ছে না'),support:T('I would like to find support','আমি সহায়তা চাই')})[el.dataset.id]);}
 else if(act==='export-data'){const consent=document.querySelector('#export-consent');if(!adult()||!consent?.checked){alert(T('Please check the consent box before exporting your personal data.','নিজের তথ্য ডাউনলোডের আগে সম্মতির ঘরে টিক দিন।'));return;}exportCSV();}
 else if(act==='timer-toggle')toggleTimer(el.dataset.mode);
 else if(act==='timer-reset')resetTimer(el.dataset.mode);
 else if(act==='meditation-speak')speakMeditation();
}
function handleSubmit(e){if(e.target.id==='profile-form'){e.preventDefault();const form=e.target;const dob=form.elements.dob.value,gender=form.elements.gender.value,age=ageFrom(dob),captcha=form.elements.captcha.value.trim();const err=document.querySelector('#profile-error');if(!Number.isInteger(age)||age<5||age>110){err.textContent=T('Choose a valid date of birth (age 5–110).','সঠিক জন্মতারিখ বেছে নিন (বয়স ৫–১১০)।');return;}if(!['Male','Female','Other','Prefer not to disclose'].includes(gender)){err.textContent=T('Select a gender option.','লিঙ্গের একটি বিকল্প বেছে নিন।');return;}if(captcha===''||Number(captcha)!==state.captcha.value){state.dob=dob;state.gender=gender;generateCaptcha();render();document.querySelector('#profile-error').textContent=T('Incorrect answer. A new calculation has been generated.','উত্তরটি ভুল হয়েছে। নতুন অঙ্ক দেওয়া হয়েছে।');return;}state.dob=dob;state.gender=gender;state.age=age;state.captcha=null;state.profileReady=true;state.entries=[];state.challenge=null;loadEntries();if(adult())try{const v=JSON.parse(localStorage.getItem('mindsage_v4_challenge')||'null');if(v&&[7,14].includes(v.duration)&&Array.isArray(v.days))state.challenge={duration:v.duration,days:v.days.filter(x=>Number.isInteger(x)&&x>=0&&x<v.duration)};}catch(e){}go('dashboard');return;}
 if(e.target.id==='assessment-form'){e.preventDefault();const form=e.target,choice=form.querySelector('input[name="answer"]:checked');if(!choice){document.querySelector('#assess-error').textContent=T('Please choose one option.','একটি উত্তর বেছে নিন।');return;}const t=state.type,v=Number(choice.value);if(state.step===10){state.contextSelections[t]=v;go('report/'+t);return;}state.answers[t][state.step]=v;if(t==='depressed'&&state.step===9&&v>0){state.step=10;render();const card=document.querySelector('.question-box');if(card)card.insertAdjacentHTML('beforeend',danger());return;}state.step++;render();return;}
 if(e.target.id==='diary-form'){e.preventDefault();const data=new FormData(e.target),mood=data.get('mood')||state.diaryChoice,energy=Number(data.get('energy')||3),note=String(data.get('note')||'').slice(0,280);state.diaryChoice=mood;state.diaryEnergy=energy;const ok=appendEntry({kind:'mood',mood,energy,note,time:new Date().toISOString(),stored:adult(),level:state.level});if(ok){render();const h=document.querySelector('.diary-form h3');if(h)h.insertAdjacentHTML('afterend',`<div class="success-note">${T('Your entry has been saved.','আপনার এন্ট্রি রাখা হয়েছে।')}</div>`);}return;}
 if(e.target.id==='chat-form'){e.preventDefault();const inp=e.target.elements.message;chatSend(inp.value);return;}
}
function handleChange(e){if(e.target.matches('input[name="answer"]')){document.querySelectorAll('.answer-choice').forEach(n=>n.classList.toggle('selected',n.querySelector('input')?.checked));}
 if(e.target.matches('input[data-focus]')){state.focusChecks[Number(e.target.dataset.focus)]=e.target.checked;render();}
 if(e.target.matches('input[name="mood"]')){state.diaryChoice=e.target.value;document.querySelectorAll('.diary-mood').forEach(n=>n.classList.toggle('selected',n.querySelector('input').checked));}
 if(e.target.matches('select[name="energy"]'))state.diaryEnergy=Number(e.target.value);
}
function toggleTimer(mode){const seconds=mode==='breathing'?120:180;if(state.timerMode!==mode){state.timerMs=0;state.timerMode=mode;state.timerPaused=true;}if(state.timerMs>=seconds*1000)state.timerMs=0;
 if(!state.timerPaused){state.timerMs+=performance.now()-state.timerStarted;state.timerPaused=true;clearInterval(state.timer);state.timer=null;}else{state.timerStarted=performance.now();state.timerPaused=false;state.timer=setInterval(()=>updateTimer(mode),100);}updateTimer(mode);}
function resetTimer(mode){stopTimer();state.timerMode=mode;state.timerMs=0;state.timerPaused=true;updateTimer(mode);}
function updateTimer(mode){const total=mode==='breathing'?120000:180000;const ms=Math.min(total,state.timerMs+(state.timerPaused?0:performance.now()-state.timerStarted));const left=Math.ceil((total-ms)/1000);const el=document.querySelector('#countdown');if(!el){stopTimer();return;}el.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');const btn=document.querySelector('#timer-toggle');if(btn)btn.innerHTML=I(state.timerPaused?'play':'pause',17)+' '+(state.timerPaused?T('Start / Resume','শুরু / আবার চালু'):T('Pause','থামুন'));if(mode==='breathing'){const phase=ms/1000%12;const name=phase<4?T('Inhale','শ্বাস নিন'):phase<6?T('Pause','থামুন'):T('Exhale','শ্বাস ছাড়ুন');const circle=document.querySelector('#breath-orbit');if(circle)circle.className='breath-orbit '+(!state.timerPaused?(phase<4?'inhale':phase<6?'hold':'exhale'):'');const strong=document.querySelector('#breath-label');if(strong)strong.textContent=left===0?T('Complete','সম্পন্ন'):state.timerPaused?T('Ready','প্রস্তুত'):name;const sub=document.querySelector('#breath-sub');if(sub)sub.textContent=state.timerPaused?T('At your pace','নিজের গতিতে'):T('Follow gently','ধীরে অনুসরণ করুন');}else{const phase=document.querySelector('#meditation-phase');if(phase)phase.textContent=left===0?T('The quiet pause is complete.','আপনার ধ্যান সম্পন্ন হয়েছে।'):ms<60000?T('Notice where your body rests.','শরীর কোথায় ভর দিয়ে আছে খেয়াল করুন।'):ms<120000?T('Gently notice your natural breathing.','স্বাভাবিক শ্বাসের দিকে মন দিন।'):T('Let thoughts pass and return to the moment.','চিন্তা এলে তাকে যেতে দিন, আবার বর্তমান মুহূর্তে ফিরুন।');}
 if(ms>=total&&!state.timerPaused){state.timerMs=total;state.timerPaused=true;clearInterval(state.timer);state.timer=null;updateTimer(mode);}
}
function speakMeditation(){if(!('speechSynthesis' in window)){alert(T('Voice guidance is not supported by this browser.','এই ব্রাউজারে কণ্ঠ নির্দেশনা নেই।'));return;}window.speechSynthesis.cancel();const script=state.lang==='bn'?'আরাম করে বসুন। কাঁধ শিথিল রাখুন। স্বাভাবিকভাবে শ্বাস নিন। মন অন্যদিকে চলে গেলে আলতো করে শ্বাসের দিকে মন ফিরিয়ে আনুন।':'Sit comfortably. Let your shoulders rest. Notice your natural breathing. If your attention wanders, gently return it to your breath.';const utterance=new SpeechSynthesisUtterance(script);utterance.lang=state.lang==='bn'?'bn-IN':'en-IN';utterance.rate=.85;window.speechSynthesis.speak(utterance);}
function exportCSV(){const rows=[['record_type','timestamp','student_category','feeling_or_mood','response_index_percent','energy_1_to_5']];state.entries.forEach(r=>rows.push([r.kind,r.time,r.level||state.level||'',r.kind==='report'?r.type:r.mood,r.kind==='report'?r.pct:'',r.kind==='mood'?r.energy:'']));const str=rows.map(row=>row.map(x=>{let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+str],{type:'text/csv;charset=utf-8'}),'Mind-sage-personal-data-'+dateStamp()+'.csv');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
